    @classmethod
    def InitFromBuf(cls, buf, pos):
        tmpRsd = RSD()
        tmpRsd.Init(buf, pos)
        return cls.InitFromObj(tmpRsd)

    @classmethod
    def InitFromPackedBuf(cls, buf, pos=0):
        n = flatbuffers.encode.Get(flatbuffers.packer.uoffset, buf, pos)
        return cls.InitFromBuf(buf, pos+n)

    @classmethod
    def InitFromObj(cls, tmpRsd):
        x = RSDT()
        x._UnPack(tmpRsd)
        return x

    # RSDT
    def _UnPack(self, RSD):
        if RSD is None:
            return
        self.RSD_ID = RSD.RSD_ID()
        self.NAME = RSD.NAME()
        self.SCENARIO_ID = RSD.SCENARIO_ID()
        self.SENSOR_ID = RSD.SENSOR_ID()
        self.SNR_ID = RSD.SNR_ID()
        self.SDR_ID = RSD.SDR_ID()
        self.APL_ID = RSD.APL_ID()
        self.WAVEFORM = RSD.WAVEFORM()
        self.INTEGRATION = RSD.INTEGRATION()
        self.CFAR = RSD.CFAR()
        self.TARGET_MODEL = RSD.TARGET_MODEL()
        self.PULSE_COUNT = RSD.PULSE_COUNT()
        self.CFAR_REFERENCE_CELL_COUNT = RSD.CFAR_REFERENCE_CELL_COUNT()
        self.CFAR_GUARD_CELL_COUNT = RSD.CFAR_GUARD_CELL_COUNT()
        self.CFAR_LOSS_DB = RSD.CFAR_LOSS_DB()
        self.TARGET_RCS_M2 = RSD.TARGET_RCS_M2()
        self.FALSE_ALARM_PROBABILITY_REQUIREMENT = RSD.FALSE_ALARM_PROBABILITY_REQUIREMENT()
        self.DETECTION_PROBABILITY_REQUIREMENT = RSD.DETECTION_PROBABILITY_REQUIREMENT()
        if not RSD.RANGE_MIsNone():
            if np is None:
                self.RANGE_M = []
                for i in range(RSD.RANGE_MLength()):
                    self.RANGE_M.append(RSD.RANGE_M(i))
            else:
                self.RANGE_M = RSD.RANGE_MAsNumpy()
        if not RSD.DETECTION_PROBABILITYIsNone():
            if np is None:
                self.DETECTION_PROBABILITY = []
                for i in range(RSD.DETECTION_PROBABILITYLength()):
                    self.DETECTION_PROBABILITY.append(RSD.DETECTION_PROBABILITY(i))
            else:
                self.DETECTION_PROBABILITY = RSD.DETECTION_PROBABILITYAsNumpy()
        if not RSD.FALSE_ALARM_PROBABILITYIsNone():
            if np is None:
                self.FALSE_ALARM_PROBABILITY = []
                for i in range(RSD.FALSE_ALARM_PROBABILITYLength()):
                    self.FALSE_ALARM_PROBABILITY.append(RSD.FALSE_ALARM_PROBABILITY(i))
            else:
                self.FALSE_ALARM_PROBABILITY = RSD.FALSE_ALARM_PROBABILITYAsNumpy()
        if not RSD.SNR_DBIsNone():
            if np is None:
                self.SNR_DB = []
                for i in range(RSD.SNR_DBLength()):
                    self.SNR_DB.append(RSD.SNR_DB(i))
            else:
                self.SNR_DB = RSD.SNR_DBAsNumpy()
        self.MAXIMUM_DETECTION_RANGE_M = RSD.MAXIMUM_DETECTION_RANGE_M()
        self.MINIMUM_DETECTABLE_RCS_M2 = RSD.MINIMUM_DETECTABLE_RCS_M2()
        self.RANGE_AT_PD_0P5_M = RSD.RANGE_AT_PD_0P5_M()
        self.RANGE_AT_PD_0P9_M = RSD.RANGE_AT_PD_0P9_M()
        self.CLUTTER_TO_NOISE_DB = RSD.CLUTTER_TO_NOISE_DB()
        self.PROPAGATION_LOSS_DB = RSD.PROPAGATION_LOSS_DB()
        self.JAMMING_TO_SIGNAL_DB = RSD.JAMMING_TO_SIGNAL_DB()
        self.BURN_THROUGH_RANGE_M = RSD.BURN_THROUGH_RANGE_M()
        if RSD.PROVENANCE() is not None:
            self.PROVENANCE = RFLProvenance.RFLProvenanceT.InitFromObj(RSD.PROVENANCE())
        self.COMPUTED_AT = RSD.COMPUTED_AT()
        self.PRODUCER_ID = RSD.PRODUCER_ID()
        if not RSD.SIGNATUREIsNone():
            if np is None:
                self.SIGNATURE = []
                for i in range(RSD.SIGNATURELength()):
                    self.SIGNATURE.append(RSD.SIGNATURE(i))
            else:
                self.SIGNATURE = RSD.SIGNATUREAsNumpy()
        if not RSD.CANONICAL_JSON_SIGNATUREIsNone():
            if np is None:
                self.CANONICAL_JSON_SIGNATURE = []
                for i in range(RSD.CANONICAL_JSON_SIGNATURELength()):
                    self.CANONICAL_JSON_SIGNATURE.append(RSD.CANONICAL_JSON_SIGNATURE(i))
            else:
                self.CANONICAL_JSON_SIGNATURE = RSD.CANONICAL_JSON_SIGNATUREAsNumpy()

    # RSDT
    def Pack(self, builder):
        if self.RSD_ID is not None:
            RSD_ID = builder.CreateString(self.RSD_ID)
        if self.NAME is not None:
            NAME = builder.CreateString(self.NAME)
        if self.SCENARIO_ID is not None:
            SCENARIO_ID = builder.CreateString(self.SCENARIO_ID)
        if self.SENSOR_ID is not None:
            SENSOR_ID = builder.CreateString(self.SENSOR_ID)
        if self.SNR_ID is not None:
            SNR_ID = builder.CreateString(self.SNR_ID)
        if self.SDR_ID is not None:
            SDR_ID = builder.CreateString(self.SDR_ID)
        if self.APL_ID is not None:
            APL_ID = builder.CreateString(self.APL_ID)
        if self.RANGE_M is not None:
            if np is not None and type(self.RANGE_M) is np.ndarray:
                RANGE_M = builder.CreateNumpyVector(self.RANGE_M)
            else:
                RSDStartRANGE_MVector(builder, len(self.RANGE_M))
                for i in reversed(range(len(self.RANGE_M))):
                    builder.PrependFloat64(self.RANGE_M[i])
                RANGE_M = builder.EndVector()
        if self.DETECTION_PROBABILITY is not None:
            if np is not None and type(self.DETECTION_PROBABILITY) is np.ndarray:
                DETECTION_PROBABILITY = builder.CreateNumpyVector(self.DETECTION_PROBABILITY)
            else:
                RSDStartDETECTION_PROBABILITYVector(builder, len(self.DETECTION_PROBABILITY))
                for i in reversed(range(len(self.DETECTION_PROBABILITY))):
                    builder.PrependFloat64(self.DETECTION_PROBABILITY[i])
                DETECTION_PROBABILITY = builder.EndVector()
        if self.FALSE_ALARM_PROBABILITY is not None:
            if np is not None and type(self.FALSE_ALARM_PROBABILITY) is np.ndarray:
                FALSE_ALARM_PROBABILITY = builder.CreateNumpyVector(self.FALSE_ALARM_PROBABILITY)
            else:
                RSDStartFALSE_ALARM_PROBABILITYVector(builder, len(self.FALSE_ALARM_PROBABILITY))
                for i in reversed(range(len(self.FALSE_ALARM_PROBABILITY))):
                    builder.PrependFloat64(self.FALSE_ALARM_PROBABILITY[i])
                FALSE_ALARM_PROBABILITY = builder.EndVector()
        if self.SNR_DB is not None:
            if np is not None and type(self.SNR_DB) is np.ndarray:
                SNR_DB = builder.CreateNumpyVector(self.SNR_DB)
            else:
                RSDStartSNR_DBVector(builder, len(self.SNR_DB))
                for i in reversed(range(len(self.SNR_DB))):
                    builder.PrependFloat64(self.SNR_DB[i])
                SNR_DB = builder.EndVector()
        if self.PROVENANCE is not None:
            PROVENANCE = self.PROVENANCE.Pack(builder)
        if self.PRODUCER_ID is not None:
            PRODUCER_ID = builder.CreateString(self.PRODUCER_ID)
        if self.SIGNATURE is not None:
            if np is not None and type(self.SIGNATURE) is np.ndarray:
                SIGNATURE = builder.CreateNumpyVector(self.SIGNATURE)
            else:
                RSDStartSIGNATUREVector(builder, len(self.SIGNATURE))
                for i in reversed(range(len(self.SIGNATURE))):
                    builder.PrependUint8(self.SIGNATURE[i])
                SIGNATURE = builder.EndVector()
        if self.CANONICAL_JSON_SIGNATURE is not None:
            if np is not None and type(self.CANONICAL_JSON_SIGNATURE) is np.ndarray:
                CANONICAL_JSON_SIGNATURE = builder.CreateNumpyVector(self.CANONICAL_JSON_SIGNATURE)
            else:
                RSDStartCANONICAL_JSON_SIGNATUREVector(builder, len(self.CANONICAL_JSON_SIGNATURE))
                for i in reversed(range(len(self.CANONICAL_JSON_SIGNATURE))):
                    builder.PrependUint8(self.CANONICAL_JSON_SIGNATURE[i])
                CANONICAL_JSON_SIGNATURE = builder.EndVector()
        RSDStart(builder)
        if self.RSD_ID is not None:
            RSDAddRSD_ID(builder, RSD_ID)
        if self.NAME is not None:
            RSDAddNAME(builder, NAME)
        if self.SCENARIO_ID is not None:
            RSDAddSCENARIO_ID(builder, SCENARIO_ID)
        if self.SENSOR_ID is not None:
            RSDAddSENSOR_ID(builder, SENSOR_ID)
        if self.SNR_ID is not None:
            RSDAddSNR_ID(builder, SNR_ID)
        if self.SDR_ID is not None:
            RSDAddSDR_ID(builder, SDR_ID)
        if self.APL_ID is not None:
            RSDAddAPL_ID(builder, APL_ID)
        RSDAddWAVEFORM(builder, self.WAVEFORM)
        RSDAddINTEGRATION(builder, self.INTEGRATION)
        RSDAddCFAR(builder, self.CFAR)
        RSDAddTARGET_MODEL(builder, self.TARGET_MODEL)
        RSDAddPULSE_COUNT(builder, self.PULSE_COUNT)
        RSDAddCFAR_REFERENCE_CELL_COUNT(builder, self.CFAR_REFERENCE_CELL_COUNT)
        RSDAddCFAR_GUARD_CELL_COUNT(builder, self.CFAR_GUARD_CELL_COUNT)
        RSDAddCFAR_LOSS_DB(builder, self.CFAR_LOSS_DB)
        RSDAddTARGET_RCS_M2(builder, self.TARGET_RCS_M2)
        RSDAddFALSE_ALARM_PROBABILITY_REQUIREMENT(builder, self.FALSE_ALARM_PROBABILITY_REQUIREMENT)
        RSDAddDETECTION_PROBABILITY_REQUIREMENT(builder, self.DETECTION_PROBABILITY_REQUIREMENT)
        if self.RANGE_M is not None:
            RSDAddRANGE_M(builder, RANGE_M)
        if self.DETECTION_PROBABILITY is not None:
            RSDAddDETECTION_PROBABILITY(builder, DETECTION_PROBABILITY)
        if self.FALSE_ALARM_PROBABILITY is not None:
            RSDAddFALSE_ALARM_PROBABILITY(builder, FALSE_ALARM_PROBABILITY)
        if self.SNR_DB is not None:
            RSDAddSNR_DB(builder, SNR_DB)
        RSDAddMAXIMUM_DETECTION_RANGE_M(builder, self.MAXIMUM_DETECTION_RANGE_M)
        RSDAddMINIMUM_DETECTABLE_RCS_M2(builder, self.MINIMUM_DETECTABLE_RCS_M2)
        RSDAddRANGE_AT_PD_0P5_M(builder, self.RANGE_AT_PD_0P5_M)
        RSDAddRANGE_AT_PD_0P9_M(builder, self.RANGE_AT_PD_0P9_M)
        RSDAddCLUTTER_TO_NOISE_DB(builder, self.CLUTTER_TO_NOISE_DB)
        RSDAddPROPAGATION_LOSS_DB(builder, self.PROPAGATION_LOSS_DB)
        RSDAddJAMMING_TO_SIGNAL_DB(builder, self.JAMMING_TO_SIGNAL_DB)
        RSDAddBURN_THROUGH_RANGE_M(builder, self.BURN_THROUGH_RANGE_M)
        if self.PROVENANCE is not None:
            RSDAddPROVENANCE(builder, PROVENANCE)
        RSDAddCOMPUTED_AT(builder, self.COMPUTED_AT)
        if self.PRODUCER_ID is not None:
            RSDAddPRODUCER_ID(builder, PRODUCER_ID)
        if self.SIGNATURE is not None:
            RSDAddSIGNATURE(builder, SIGNATURE)
        if self.CANONICAL_JSON_SIGNATURE is not None:
            RSDAddCANONICAL_JSON_SIGNATURE(builder, CANONICAL_JSON_SIGNATURE)
        RSD = RSDEnd(builder)
        return RSD
